-- SafetyTraining v20.053a
-- Reconcile live scaffolding initial/update family (art. 136 + Allegato XXI).
-- 16 didactic units, exact 4h/10h/14h initial composition and 4h update composition.

DO $do$
DECLARE r jsonb; c jsonb; v_lu uuid; v_luv uuid; v_course uuid; v_cv uuid; v_module uuid; v_content jsonb; v_practical boolean;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"k":"ponteggi:law:system","t":"Quadro normativo, rischi e responsabilità","s":"Inquadrare lavori in quota, soggetti, obblighi e principali cause di infortunio nel montaggio ponteggi.","m":120,"v":"ponteggi-v2","p":false,"f":["Titolo IV","art.136","ruoli e responsabilità","analisi dei rischi","buone prassi","eventi e violazioni"],"case":"Una squadra vuole iniziare prima dell’arrivo del preposto previsto: ricostruire ruoli, motivo dello stop e condizioni per l’avvio."},
    {"k":"ponteggi:law:height","t":"Cantieri e lavori in quota: protezioni e coordinamento","s":"Collegare ponteggio, protezione collettiva, DPI, area di cantiere e interferenze.","m":120,"v":"ponteggi-v2","p":false,"f":["lavori in quota","protezioni collettive","DPI","coordinamento","area sottostante","emergenza"],"case":"Il montaggio interessa un ingresso ancora usato da altri lavoratori: progettare segregazione, deviazione e sequenza."},
    {"k":"ponteggi:tech:pimus","t":"PiMUS, autorizzazione, disegno esecutivo e progetto","s":"Leggere la documentazione tecnica come istruzione operativa del ponteggio reale.","m":120,"v":"ponteggi-v2","p":false,"f":["PiMUS","autorizzazione ministeriale","libretto","disegno esecutivo","progetto","configurazione reale"],"case":"La facciata ha rientranze non contemplate nello schema: stabilire quali verifiche e documenti servono prima del montaggio."},
    {"k":"ponteggi:tech:dpi","t":"DPI anticaduta nel montaggio ponteggi","s":"Usare sistemi individuali nelle fasi non ancora protette collettivamente, conoscendone limiti e controlli.","m":120,"v":"ponteggi-v2","p":true,"f":["imbracatura","collegamenti","assorbitore","controllo pre-uso","continuità protezione","spazio libero"],"case":"Durante la posa del primo livello manca la protezione definitiva: individuare sistema previsto, punti utilizzabili e criterio di stop."},
    {"k":"ponteggi:tech:anchors","t":"Ancoraggi e stabilità del ponteggio","s":"Comprendere funzione, posizione e controllo degli ancoraggi e dei controventi.","m":120,"v":"ponteggi-v2","p":true,"f":["ancoraggi","supporto","schema","passo","controventi","stabilità globale","rimozione controllata"],"case":"Un’impresa chiede di rimuovere due ancoraggi per installare serramenti: definire perché serve ripianificazione prima di agire."},
    {"k":"ponteggi:tech:checks","t":"Verifiche di primo impianto, periodiche e straordinarie","s":"Riconoscere controlli necessari prima dell’uso e dopo eventi o trasformazioni.","m":120,"v":"ponteggi-v2","p":false,"f":["appoggi","verticalità","impalcati","parapetti","ancoraggi","vento","urti","trasformazioni"],"case":"Dopo forte vento un telo è allentato e una basetta sembra ceduta: definire interdizione, controllo e riapertura."},
    {"k":"ponteggi:tech:sequence","t":"Sequenza di montaggio, trasformazione e smontaggio","s":"Pianificare l’ordine delle operazioni mantenendo stabilità e protezione della squadra.","m":120,"v":"ponteggi-v2","p":false,"f":["sequenza","materiali","protezioni progressive","trasformazioni","smontaggio","mantenimento ancoraggi"],"case":"Pianificare una trasformazione per creare un passaggio mantenendo stabilità, protezioni e tracciabilità."},
    {"k":"ponteggi:practice:prep","t":"Preparazione area, componenti e DPI","s":"Preparare area, materiali, ruoli e dispositivi prima del primo elemento.","m":120,"v":"ponteggi-v2","p":true,"f":["delimitazione","compatibilità componenti","controllo DPI","attrezzi","briefing","GO/NO-GO"],"case":"Preparare da zero una postazione didattica e motivare ogni controllo prima dell’inizio."},
    {"k":"ponteggi:practice:tg","t":"Montaggio/smontaggio ponteggio a tubi e giunti","s":"Eseguire sequenze base su PTG con protezioni, collegamenti e controllo geometrico.","m":120,"v":"ponteggi-v2","p":true,"f":["montanti","correnti","diagonali","giunti","impalcati","ancoraggi","smontaggio"],"case":"Montare una porzione didattica PTG e poi smontarla mantenendo ancoraggi e protezioni finché necessari."},
    {"k":"ponteggi:practice:frame","t":"Montaggio/smontaggio ponteggio a telai prefabbricati","s":"Eseguire sequenze base su telai prefabbricati rispettando schema e protezioni.","m":120,"v":"ponteggi-v2","p":true,"f":["telai","diagonali","impalcati","parapetti","ancoraggi","accessi"],"case":"Costruire due livelli didattici; il docente introduce una non conformità e il corsista deve fermarsi e correggere."},
    {"k":"ponteggi:practice:multidirectional","t":"Montaggio/smontaggio ponteggio multidirezionale","s":"Eseguire sequenze su sistema a montanti e traversi prefabbricati comprendendo la logica dei nodi.","m":120,"v":"ponteggi-v2","p":true,"f":["montanti","traversi","correnti","nodi","diagonali","impalcati","geometria"],"case":"Realizzare un angolo/rientro didattico mantenendo geometria, controventatura e protezioni."},
    {"k":"ponteggi:practice:anchors","t":"Realizzazione e verifica pratica degli ancoraggi","s":"Installare e controllare ancoraggi previsti senza improvvisare supporti o posizioni.","m":120,"v":"ponteggi-v2","p":true,"f":["posizione","supporto","componenti","serraggio","verifica","impossibilità di posa"],"case":"Il punto previsto coincide con supporto degradato: riconoscere la condizione di stop e richiedere soluzione tecnica."},
    {"k":"ponteggi:practice:transform","t":"Trasformazione controllata e verifica finale","s":"Gestire una modifica senza perdere stabilità, protezioni e tracciabilità.","m":120,"v":"ponteggi-v2","p":true,"f":["interdizione","sequenza","protezione temporanea","ancoraggi","verifica","riapertura"],"case":"Trasformare una campata per il passaggio di materiale e riportarla in condizione d’uso verificata."},
    {"k":"ponteggi:practice:rescue","t":"Prima emergenza e salvataggio nel montaggio ponteggi","s":"Conoscere allarme, recupero previsto e limiti del soccorso della squadra.","m":120,"v":"ponteggi-v2","p":true,"f":["caduta arrestata","sospensione","allarme","recupero","accesso soccorsi","ritiro DPI"],"case":"Simulare a bassa esposizione un lavoratore sospeso e attivare il piano senza manovre improvvisate."},
    {"k":"ponteggi:update:theory","t":"Aggiornamento normativo, PiMUS e anomalie ricorrenti","s":"Rivedere evoluzioni normative/tecniche, modifiche dei sistemi, eventi e criteri di stop.","m":60,"v":"ponteggi-update-v2","p":false,"f":["novità","PiMUS","DPI","ancoraggi","near miss","cambiamenti tecnici"],"case":"Dopo l’ultimo corso viene introdotto un sistema di protezione anticipata: confrontare nuova sequenza e vecchie abitudini."},
    {"k":"ponteggi:update:practice","t":"Aggiornamento tecnico-pratico: montaggio, ancoraggi, trasformazione ed emergenza","s":"Rinnovare abilità pratiche e capacità di riconoscere una sequenza non più sicura.","m":180,"v":"ponteggi-update-v2","p":true,"f":["controllo DPI","montaggio","ancoraggio","trasformazione","stop","emergenza","debriefing"],"case":"Esercitazione integrata con una non conformità introdotta dal docente e ripristino corretto prima della prosecuzione."}
  ]::jsonb) LOOP
    v_practical := (r->>'p')::boolean;
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata) VALUES(r->>'k',r->>'t',r->>'s',(r->>'m')::int,'SafetyTraining ponteggi-v2',array['safetytraining','ponteggi',r->>'v'],true,jsonb_build_object('source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','reuse_policy','reference_and_original_rewrite'),'learner_ready',true,'teacher_ready',true,'practical_focus',v_practical,'didactic_version',r->>'v')) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;
    v_content := jsonb_build_object('case',r->>'case','norm','D.Lgs. 81/2008 art. 136 e Allegato XXI; PiMUS, autorizzazione/progetto e istruzioni applicabili alla configurazione reale.','quiz',jsonb_build_object('options',jsonb_build_array('Proseguire perché la squadra è esperta','Adattare liberamente lo schema','Fermarsi, confrontare la configurazione con PiMUS/documentazione e riprendere solo dopo una soluzione verificata','Rimuovere temporaneamente la protezione'),'question','Se la configurazione reale non corrisponde a quella prevista, qual è il comportamento corretto?','explanation','Il ponteggio non si modifica per abitudine: stabilità, protezioni e sequenza devono restare coerenti con PiMUS e documentazione tecnica.','correct_index',2),'focus',r->'f','title',r->>'t','detail','Questa unità sviluppa una competenza direttamente applicabile alle operazioni sui ponteggi. Il contenuto va sempre collegato al PiMUS, all’autorizzazione o progetto e alla configurazione realmente utilizzata. Il corsista deve spiegare non solo come eseguire il passaggio ma quale rischio viene controllato, quale elemento non può essere modificato liberamente, quando la sequenza deve fermarsi e quale verifica consente la ripresa.','minutes',(r->>'m')::int,'quality',jsonb_build_object('learner_ready',true,'teacher_ready',true,'scenario_based',true,'practical_focus',v_practical),'summary',r->>'s','visuals',jsonb_build_array('piramide-pericoli.svg','procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg'),'procedure',case when v_practical then jsonb_build_array('preparare area, componenti e DPI','verificare la sequenza prevista da PiMUS/documentazione','eseguire la manovra mantenendo protezione e stabilità','arrestarsi davanti a difformità o perdita di protezione','completare controllo finale e comunicare la riapertura') else jsonb_build_array('descrivere fase e configurazione reale','individuare rischi e soggetti coinvolti','confrontare con PiMUS, libretto/progetto e procedura','definire misura, responsabilità e criterio di stop','verificare che la soluzione sia attuabile prima di proseguire') end,'common_errors',jsonb_build_array('lavorare per abitudine invece che secondo la sequenza prevista','considerare intercambiabili componenti o configurazioni senza verifica','rimuovere protezioni o ancoraggi prima del momento previsto','riaprire all’uso senza controllo dopo modifica o evento anomalo'),'delivery_note','Il materiale resta disponibile integralmente; la quota pratica richiede esercitazione effettiva e non è sostituita dalla sola consultazione digitale.','guided_activity',jsonb_build_array('analisi di PiMUS/disegno o scenario','identificazione del rischio e della barriera','decisione GO/NO-GO','esecuzione o simulazione guidata','debriefing e verifica del ripristino'),'didactic_version',r->>'v','evidence_sources',jsonb_build_array(jsonb_build_object('url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.-quaderni-tecnici-per-i-cantieri-temporanei-o-mobili-sul-portale-inail-la-nuova-edizione.html','use','technical_reference','title','Quaderni tecnici per i cantieri temporanei o mobili','authority','INAIL','checked_on','2026-10-15'),jsonb_build_object('url','https://www.regione.piemonte.it/governo/bollettino/abbonati/2025/30/attach/dgr_01413_1050_23072025.pdf','use','asr2025_compliance_crosscheck','title','Indicazioni operative per la formazione alla salute e sicurezza - edizione 2025','authority','Regione Piemonte','checked_on','2026-10-15')),'final_assessment',false,'teacher_expansion',case when v_practical then 'Usare ponteggio o addestratore coerente con la tipologia trattata, area segregata, DPI e componenti controllati. Ogni partecipante esegue personalmente. Inserire una anomalia controllata e valutare riconoscimento, stop, comunicazione e ripristino.' else 'Usare PiMUS, estratti del libretto/progetto, disegni e fotografie. Far individuare incoerenze tra documento e scenario e chiedere una decisione operativa motivata.' end,'teacher_source_prompt','Collegare il requisito normativo a una situazione di cantiere concreta: individuare pericolo, barriera collettiva prioritaria, verifica prima dell’uso, condizione di stop e azione correttiva.');
    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) VALUES(v_lu,1,'draft',v_content,null) ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'inail-quaderni-cantieri','technical_reference','Riferimento per opere provvisionali, protezioni collettive, ancoraggi, cadute e procedure di cantiere.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on;
  END LOOP;

  INSERT INTO public.courses(stable_key,title,family,description,nominal_minutes,certification_mode,active,metadata) VALUES('ponteggi_28h','Montaggio, smontaggio e trasformazione ponteggi – 28h','Lavori in quota specialistici','Corso teorico-pratico per lavoratori e preposti addetti al montaggio, smontaggio e trasformazione dei ponteggi fissi ai sensi dell’art. 136 e Allegato XXI D.Lgs. 81/2008.',1680,'internal_learning',true,'{"blueprint_key":"ponteggi_28h","didactic_version":"ponteggi-v2","regulatory_basis":"D.Lgs. 81/2008 art. 136 e Allegato XXI","material_complete":true,"attendance_min_pct":90,"requires_admin_review":true,"learner_catalog_hidden":true,"intermediate_test_required":true,"final_practical_test_required":true,"delivery_rules_are_metadata_only":true}'::jsonb) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,family=excluded.family,description=excluded.description,nominal_minutes=excluded.nominal_minutes,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_course;
  INSERT INTO public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot,published_at) VALUES(v_course,1,'draft','{"total_minutes":1680,"didactic_version":"ponteggi-v2","material_complete":true}'::jsonb,'{"basis":"D.Lgs. 81/2008 art. 136 e Allegato XXI"}'::jsonb,null) ON CONFLICT(course_id,version_number) DO UPDATE SET status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot,published_at=null RETURNING id INTO v_cv;
  FOR c IN SELECT value FROM jsonb_array_elements('[{"k":"p-law","t":"Modulo giuridico-normativo – 4h","p":1,"m":240},{"k":"p-tech","t":"Modulo tecnico – 10h","p":2,"m":600},{"k":"p-practice","t":"Modulo pratico – 14h","p":3,"m":840}]'::jsonb) LOOP INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,c->>'k',c->>'t',(c->>'p')::int,(c->>'m')::int) ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=excluded.position,nominal_minutes=excluded.nominal_minutes; END LOOP;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"m":"p-law","k":"ponteggi:law:system","p":1,"g":false},{"m":"p-law","k":"ponteggi:law:height","p":2,"g":false},{"m":"p-tech","k":"ponteggi:tech:pimus","p":1,"g":false},{"m":"p-tech","k":"ponteggi:tech:dpi","p":2,"g":true},{"m":"p-tech","k":"ponteggi:tech:anchors","p":3,"g":true},{"m":"p-tech","k":"ponteggi:tech:checks","p":4,"g":false},{"m":"p-tech","k":"ponteggi:tech:sequence","p":5,"g":false},{"m":"p-practice","k":"ponteggi:practice:prep","p":1,"g":true},{"m":"p-practice","k":"ponteggi:practice:tg","p":2,"g":true},{"m":"p-practice","k":"ponteggi:practice:frame","p":3,"g":true},{"m":"p-practice","k":"ponteggi:practice:multidirectional","p":4,"g":true},{"m":"p-practice","k":"ponteggi:practice:anchors","p":5,"g":true},{"m":"p-practice","k":"ponteggi:practice:transform","p":6,"g":true},{"m":"p-practice","k":"ponteggi:practice:rescue","p":7,"g":true}]'::jsonb) LOOP SELECT id INTO v_module FROM public.course_modules WHERE course_version_id=v_cv AND module_key=r->>'m'; SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>'k'; INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) VALUES(v_module,v_luv,(r->>'p')::int,true,0,true,jsonb_build_object('material_complete',true,'practical_or_guided',(r->>'g')::boolean)) ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules; END LOOP;

  INSERT INTO public.courses(stable_key,title,family,description,nominal_minutes,certification_mode,active,metadata) VALUES('agg_ponteggi_4h','Aggiornamento addetti/preposti ponteggi – 4h','Lavori in quota specialistici','Aggiornamento quadriennale per addetti e preposti al montaggio, smontaggio e trasformazione ponteggi: 4 ore, di cui 3 tecnico-pratiche.',240,'internal_learning',true,'{"blueprint_key":"agg_ponteggi_4h","renewal_months":48,"didactic_version":"ponteggi-update-v2","regulatory_basis":"D.Lgs. 81/2008 Allegato XXI","material_complete":true,"requires_admin_review":true,"learner_catalog_hidden":true,"technical_practical_minutes":180,"delivery_rules_are_metadata_only":true}'::jsonb) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,family=excluded.family,description=excluded.description,nominal_minutes=excluded.nominal_minutes,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_course;
  INSERT INTO public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot,published_at) VALUES(v_course,1,'draft','{"total_minutes":240,"didactic_version":"ponteggi-update-v2","material_complete":true}'::jsonb,'{"basis":"D.Lgs. 81/2008 Allegato XXI"}'::jsonb,null) ON CONFLICT(course_id,version_number) DO UPDATE SET status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot,published_at=null RETURNING id INTO v_cv;
  INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,'p-upd','Aggiornamento ponteggi – 4h',1,240) ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=1,nominal_minutes=240 RETURNING id INTO v_module;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"k":"ponteggi:update:theory","p":1,"g":false},{"k":"ponteggi:update:practice","p":2,"g":true}]'::jsonb) LOOP SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>'k'; INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) VALUES(v_module,v_luv,(r->>'p')::int,true,0,true,jsonb_build_object('material_complete',true,'practical_or_guided',(r->>'g')::boolean)) ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules; END LOOP;
END $do$;
